mapper.select:
select dbo.getCommonName('area', a.area_cd) as area_cd ,dbo.getItemName(a.item_cd) as item_name ,b.make_No ,b.lot_no ,b.lot_no2 ,b.batch_status ,isnull(m.test_state, 'N') as test_state ,m.qc_test_type ,c.proc_order_date as charging_date ,d.proc_order_date as packing_date ,b.work_batch_id ,b.work_batch_id ,m.qc_proc_test_mst_id from TB_WORK_ORDER_MST a inner join TB_WORK_ORDER_BATCH b on b.work_order_id = a.work_order_id left outer join tb_qc_proc_test_mst m on m.work_batch_id = b.work_batch_id inner join TB_WORK_ORDER_PROC c on c.work_batch_id = b.work_batch_id and c.proc_cd = 'PRC004' inner join TB_WORK_ORDER_PROC d on d.work_batch_id = b.work_batch_id and d.proc_cd = 'PRC005' where b.batch_status != '99' and b.batch_status >= '22' and d.proc_order_date between #{strDate} and #{endDate}
and a.area_cd = #{areaCd}
and a.item_cd = #{itemCd}
and b.batch_status = #{batchStatus}
and m.test_state) =#{testState}
order by a.work_order_date desc, a.seq desc

mapper.update:
update tb_qc_proc_test_sample
set    sample_date = #{sampleDate}
      ,qty1        =#{qty1}
      ,qty2        =#{qty2}
      ,qty3        =#{qty3}
      ,qty4        =#{qty4}
      ,qty5        =#{qty5}
      ,qty6        =#{qty6}
      ,qty7        =#{qty7}
      ,qty8        =#{qty8}
      ,qty9        =#{qty9}
      ,upd_id      = #{userId}
      ,upd_dt      = getdate()
where  qc_proc_test_sample_id = #{qcProcTestSampleId}

update tb_qc_proc_test_mst
set    etc = #{etc}
      ,upd_id = #{userId}
      ,upd_dt = getdate()
where qc_proc_test_mst_id = #{qcProcTestMstId}

update tb_qc_proc_test_method
set    test_item   = #{testItem}
      ,test_method = #{testMethod}
      ,test_result = #{testResult}
      ,tester_id   = #{testerId}
      ,order_dist  = #{orderDist}
      ,upd_id       = #{userId}
      ,upd_dt       = getdate()
where  qc_proc_test_method_id = #{qcProcTestMethodId}

update tb_qc_proc_test_detail
set    test_time    = #{testTime}
      ,line1        =#{line1}
      ,line2        =#{line2}
      ,line3        =#{line3}
      ,line4        =#{line4}
      ,line5        =#{line5}
      ,line6        =#{line6}
      ,line7        =#{line7}
      ,line8        =#{line8}
      ,line9        =#{line9}
      ,line10       =#{line10}
      ,pass_yn      =#{passYn}
      ,order_dist   =#{orderDist}
      ,upd_id       = #{userId}
      ,upd_dt       = getdate()
where  qc_proc_test_detail_id = #{qcProcTestDetailId}

update tb_qc_proc_test_line
set    line_name = #{lineName}
      ,scale_cd  = #{scaleCd}
      ,order_dist = #{orderDist}
      ,upd_id = #{userId}
      ,upd_dt = getdate()
where  qc_proc_test_line_id = #{qcProcTestLineId}
